import{_ as d,o as r,c as a,a5 as e}from"./chunks/framework.CXroN2RO.js";const c=JSON.parse('{"title":"用語集","description":"","frontmatter":{"title":"用語集","study":{"source":"C++ Wiki","kind":"用語","status":"既存原稿","summary":"五十音順・アルファベット順の混合で、カテゴリごとに整理しています。各用語の詳細は詳細ページへのリンクを参照してください。 目次に戻る"}},"headers":[],"relativePath":"guide/cpp-glossary.md","filePath":"guide/cpp-glossary.md"}'),n={name:"guide/cpp-glossary.md"};function s(l,t,i,o,h,u){return r(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="用語集" tabindex="-1">用語集 <a class="header-anchor" href="#用語集" aria-label="Permalink to &quot;用語集&quot;">​</a></h1><p>五十音順・アルファベット順の混合で、カテゴリごとに整理しています。各用語の詳細は詳細ページへのリンクを参照してください。</p><h2 id="設計の基礎用語" tabindex="-1">設計の基礎用語 <a class="header-anchor" href="#設計の基礎用語" aria-label="Permalink to &quot;設計の基礎用語&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用語</th><th>一言定義</th><th>詳細</th></tr></thead><tbody><tr><td>責務</td><td>そのコードが引き受けている仕事と、その変更理由</td><td><a href="/study/design/foundations/responsibility-and-separation.html">責務と関心の分離</a></td></tr><tr><td>関心の分離</td><td>異なる理由で変更されるコードを別の場所に置くこと</td><td>同上</td></tr><tr><td>凝集度</td><td>モジュール内部の要素がどれだけ関連し合っているか(高いほど良い)</td><td><a href="/study/design/foundations/cohesion-and-coupling.html">凝集度と結合度</a></td></tr><tr><td>結合度</td><td>モジュール同士が互いをどれだけ知っているか(低いほど良い)</td><td>同上</td></tr><tr><td>依存</td><td>AがBを知っており、Bの変更でAが壊れうる関係</td><td><a href="/study/design/foundations/dependency.html">依存関係</a></td></tr><tr><td>循環依存</td><td>A→B→Aと依存が輪になった状態。分離・テスト不能の原因</td><td>同上</td></tr><tr><td>抽象化</td><td>使う側に重要なことだけ残し詳細を削ぎ落とすこと</td><td><a href="/study/design/foundations/abstraction-encapsulation.html">抽象化・カプセル化</a></td></tr><tr><td>カプセル化</td><td>データとそれを操作するコードを1つにまとめること</td><td>同上</td></tr><tr><td>情報隠蔽</td><td>変わりそうな決定を外から見えなくすること</td><td>同上</td></tr><tr><td>継承</td><td>is-a関係。基底の実装とインターフェースを受け継ぐ</td><td><a href="/study/design/foundations/inheritance-delegation-composition.html">継承・委譲・コンポジション</a></td></tr><tr><td>コンポジション</td><td>has-a関係。機能を部品として持つ</td><td>同上</td></tr><tr><td>委譲</td><td>仕事を持っている部品に転送すること</td><td>同上</td></tr><tr><td>ポリモーフィズム(多態)</td><td>同じ呼び出しが相手によって違う振る舞いをすること</td><td><a href="/study/design/foundations/polymorphism-interface.html">ポリモーフィズム</a></td></tr><tr><td>インターフェース</td><td>「何ができるか」だけを定めた約束</td><td>同上</td></tr><tr><td>YAGNI</td><td>You Aren&#39;t Gonna Need It。今必要ない機能は作らない</td><td><a href="/study/design/foundations/yagni-kiss-dry.html">YAGNI・KISS・DRY</a></td></tr><tr><td>KISS</td><td>Keep It Simple。同じ問題を解けるなら単純な方を選ぶ</td><td>同上</td></tr><tr><td>DRY</td><td>Don&#39;t Repeat Yourself。同じ<strong>知識</strong>を2か所に書かない</td><td>同上</td></tr><tr><td>早すぎる抽象化</td><td>具体例が揃う前の共通化。間違った抽象を生みやすい</td><td>同上</td></tr><tr><td>早すぎる最適化</td><td>計測せず推測で複雑化すること</td><td>同上</td></tr><tr><td>技術的負債</td><td>「今すぐ動かす」ために「後で直すコスト」を借りること</td><td><a href="/study/design/foundations/tech-debt-and-refactoring.html">技術的負債</a></td></tr><tr><td>コードの臭い</td><td>バグではないが設計問題を示唆する兆候</td><td>同上</td></tr><tr><td>リファクタリング</td><td>外部の振る舞いを変えずに内部構造を改善すること</td><td>同上</td></tr><tr><td>SRP/OCP/LSP/ISP/DIP</td><td>SOLID原則の5つ</td><td><a href="/study/design/solid/">第2部</a></td></tr><tr><td>ショットガン手術</td><td>1つの変更で多数のファイルを修正する羽目になる状態</td><td><a href="/study/design/solid/srp.html">SRP</a></td></tr></tbody></table><h2 id="パターン用語" tabindex="-1">パターン用語 <a class="header-anchor" href="#パターン用語" aria-label="Permalink to &quot;パターン用語&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用語</th><th>一言定義</th><th>詳細</th></tr></thead><tbody><tr><td>デザインパターン</td><td>繰り返し現れる設計問題への定型解のカタログ</td><td><a href="/study/design/patterns/">第3部</a></td></tr><tr><td>GoF</td><td>Gang of Four。23パターンを整理した4人の著者</td><td>同上</td></tr><tr><td>Singleton</td><td>唯一のインスタンス+全域アクセス(乱用注意)</td><td><a href="/study/design/patterns/singleton.html">Singleton</a></td></tr><tr><td>Observer</td><td>変化を購読者に通知する(C#のeventの正体)</td><td><a href="/study/design/patterns/observer.html">Observer</a></td></tr><tr><td>lapsed listener</td><td>購読解除忘れで死んだ購読者がリストに残る問題</td><td>同上</td></tr><tr><td>ダブルディスパッチ</td><td>実行時の型×操作の2軸で処理が選ばれる仕組み</td><td><a href="/study/design/patterns/visitor.html">Visitor</a></td></tr><tr><td>Game Loop</td><td>入力→更新→描画を回し続けるゲームの心臓部</td><td><a href="/study/game/patterns/game-loop-and-update.html">Game Loop</a></td></tr><tr><td>固定タイムステップ</td><td>更新を固定刻み(1/60秒等)で行う方式。再現条件をそろえやすいが、単独では決定性を保証しない</td><td>同上</td></tr><tr><td>ECS</td><td>Entity Component System。データとロジックを分離し配列で処理</td><td><a href="/study/game/patterns/component-and-ecs.html">Component と ECS</a></td></tr><tr><td>Pub/Sub</td><td>チャネル経由で発行者と購読者が互いに匿名の通知方式</td><td><a href="/study/game/patterns/event-queue-and-pubsub.html">Event Queue・Pub/Sub</a></td></tr><tr><td>Service Locator</td><td>サービスの「電話帳」を1つ置き、必要な側が問い合わせる</td><td><a href="/study/game/patterns/service-locator-and-di.html">Service LocatorとDI</a></td></tr><tr><td>DI(依存性注入)</td><td>必要な依存を外から渡してもらう方式</td><td>同上</td></tr><tr><td>Object Pool</td><td>生成破棄の激しいオブジェクトを確保済みプールで使い回す</td><td><a href="/study/game/patterns/object-pool.html">Object Pool</a></td></tr><tr><td>世代付きハンドル</td><td>index+世代番号で「解放済み参照」を検出できる参照方式</td><td>同上</td></tr><tr><td>Dirty Flag</td><td>変更があったときだけ高価な再計算をする目印</td><td><a href="/study/game/patterns/optimization-patterns.html">最適化系パターン</a></td></tr><tr><td>Spatial Partition</td><td>空間をグリッド等に分割し近傍だけ調べる構造</td><td>同上</td></tr><tr><td>Data Locality</td><td>使うデータをメモリ上で隣接させて速くする原則</td><td>同上</td></tr><tr><td>Double Buffer</td><td>読む用と書く用の2枚を交換し、順序問題を消す</td><td>同上</td></tr><tr><td>Type Object</td><td>「種類」をクラスでなくデータで表す</td><td><a href="/study/game/patterns/type-object-and-sandbox.html">Type Object</a></td></tr><tr><td>FSM</td><td>有限ステートマシン。有限個の状態+遷移ルール</td><td><a href="/study/game/patterns/state-machines.html">ステートマシン</a></td></tr><tr><td>HSM</td><td>階層型ステートマシン。共通遷移を親状態に括り出す</td><td>同上</td></tr><tr><td>Behavior Tree</td><td>毎フレーム根から評価する行動選択ツリー</td><td><a href="/study/game/patterns/behavior-tree-and-blackboard.html">BTとBlackboard</a></td></tr><tr><td>Blackboard</td><td>AIの知識を集約する共有メモ帳</td><td>同上</td></tr><tr><td>MVC/MVP/MVVM</td><td>ModelとViewを分離するUI設計の3流派</td><td><a href="/study/game/patterns/mvc-mvp-mvvm.html">MVC・MVP・MVVM</a></td></tr><tr><td>データバインディング</td><td>ViewModelとViewを自動同期する機構(MVVMの前提)</td><td>同上</td></tr><tr><td>Reactive Programming</td><td>値の変化をストリームとして合成・購読するスタイル</td><td><a href="/study/game/patterns/reactive-and-message-bus.html">Reactive</a></td></tr></tbody></table><h2 id="c-言語用語" tabindex="-1">C++言語用語 <a class="header-anchor" href="#c-言語用語" aria-label="Permalink to &quot;C++言語用語&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用語</th><th>一言定義</th><th>詳細</th></tr></thead><tbody><tr><td>値セマンティクス</td><td>代入=中身のコピー、という既定の意味論</td><td><a href="/study/languages/cpp/values-pointers-references.html">値と参照</a></td></tr><tr><td>ポインタ</td><td>アドレスを入れる変数。null・差し替え可</td><td>同上</td></tr><tr><td>参照</td><td>既存の変数の別名。null不可・差し替え不可</td><td>同上</td></tr><tr><td>const correctness</td><td>変更しないものにconstを付け通す規律</td><td><a href="/study/languages/cpp/const-correctness.html">const</a></td></tr><tr><td>SSO</td><td>小文字列最適化。短い文字列をヒープ確保なしで持つ実装</td><td><a href="/study/languages/cpp/arrays-and-strings.html">配列と文字列</a></td></tr><tr><td>ムーブ</td><td>コピーの代わりに中身(所有権)を移す仕組み</td><td><a href="/study/languages/cpp/ctor-dtor-copy-move.html">コピーとムーブ</a></td></tr><tr><td>Rule of Zero/Three/Five</td><td>特殊メンバ関数を書く/書かないの経験則</td><td>同上</td></tr><tr><td>RAII</td><td>リソースの確保と解放をオブジェクトの寿命に一致させる</td><td><a href="/study/languages/cpp/raii.html">RAII</a></td></tr><tr><td>仮想関数</td><td>実行時に実際の型のメソッドが呼ばれる関数</td><td><a href="/study/languages/cpp/inheritance-and-virtual.html">継承と仮想関数</a></td></tr><tr><td>純粋仮想関数</td><td><code>= 0</code>で宣言し、派生に実装を強制する仮想関数</td><td>同上</td></tr><tr><td>抽象クラス</td><td>純粋仮想を持ちインスタンス化できないクラス</td><td>同上</td></tr><tr><td>スライシング</td><td>派生を値コピーすると基底部分だけ写る事故</td><td>同上</td></tr><tr><td>オーバーロード</td><td>同名関数を引数違いで複数定義(コンパイル時解決)</td><td><a href="/study/languages/cpp/overloading.html">オーバーロード</a></td></tr><tr><td>テンプレート</td><td>型を引数にしたコードの雛形。使用時に実体化</td><td><a href="/study/languages/cpp/templates-and-concepts.html">テンプレート</a></td></tr><tr><td>concepts</td><td>テンプレート引数の制約を宣言するC++20機能</td><td>同上</td></tr><tr><td>ラムダ式</td><td>その場で作る無名関数オブジェクト。キャプチャ可</td><td><a href="/study/languages/cpp/lambdas-and-functions.html">ラムダ</a></td></tr><tr><td>std::function</td><td>呼び出せるものを統一的に入れる箱(型消去)</td><td>同上</td></tr><tr><td>enum class</td><td>スコープ付き・暗黙変換なしの列挙型(推奨)</td><td><a href="/study/languages/cpp/enums-and-namespaces.html">enum</a></td></tr><tr><td>スタック巻き戻し</td><td>例外発生時にデストラクタを実行しながら遡る処理</td><td><a href="/study/languages/cpp/exceptions.html">例外</a></td></tr><tr><td>constexpr</td><td>コンパイル時に実行できる計算・定数</td><td><a href="/study/languages/cpp/auto-and-constexpr.html">constexpr</a></td></tr><tr><td>consteval</td><td>必ずコンパイル時に実行される関数(C++20)</td><td>同上</td></tr><tr><td>inline</td><td>現代の意味は「多重定義の許可」(展開は最適化器の判断)</td><td><a href="/study/languages/cpp/static-inline-friend.html">static・inline・friend</a></td></tr><tr><td>dynamic_cast</td><td>実行時検査つきダウンキャスト(RTTI使用)</td><td><a href="/study/languages/cpp/casts.html">キャスト</a></td></tr><tr><td>unique_ptr / shared_ptr / weak_ptr</td><td>単独所有/共有所有/弱参照のスマートポインタ</td><td><a href="/study/languages/cpp/smart-pointers.html">スマートポインタ</a></td></tr><tr><td>イテレータ無効化</td><td>コンテナ操作で既存のイテレータ・参照が無効になること</td><td><a href="/study/languages/cpp/stl.html">STL</a></td></tr><tr><td>未定義動作(UB)</td><td>標準が一切の要求をしない状態。何が起きてもよい</td><td><a href="/study/languages/cpp/undefined-behavior.html">未定義動作</a></td></tr><tr><td>実装定義</td><td>処理系が決めて文書化する動作(intのサイズ等)</td><td>同上</td></tr><tr><td>未規定</td><td>候補のどれかになるが文書化義務のない動作(評価順等)</td><td>同上</td></tr></tbody></table><h2 id="ビルド・内部用語" tabindex="-1">ビルド・内部用語 <a class="header-anchor" href="#ビルド・内部用語" aria-label="Permalink to &quot;ビルド・内部用語&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用語</th><th>一言定義</th><th>詳細</th></tr></thead><tbody><tr><td>プリプロセッサ</td><td>#include展開・#define置換を行うテキスト処理</td><td><a href="/study/runtime/cpp-internals/build-pipeline-journey.html">ビルドの旅</a></td></tr><tr><td>翻訳単位</td><td>1つの.cppからincludeを展開してできる、独立コンパイルの単位</td><td><a href="/study/runtime/cpp-internals/translation-units-and-headers.html">翻訳単位</a></td></tr><tr><td>宣言と定義</td><td>存在の約束(何度でも可)と実体(原則1つ)</td><td>同上</td></tr><tr><td>ODR</td><td>One Definition Rule。定義はプログラム全体で1つ</td><td>同上</td></tr><tr><td>前方宣言</td><td>「この型が存在する」とだけ伝える宣言。include削減の道具</td><td>同上</td></tr><tr><td>include guard / #pragma once</td><td>同一ヘッダーの二重取り込み防止</td><td>同上</td></tr><tr><td>シンボル</td><td>リンカが使う「名前→機械語/データの場所」の項目</td><td><a href="/study/runtime/cpp-internals/symbols-and-linkage.html">シンボル</a></td></tr><tr><td>名前修飾(mangling)</td><td>関数名に型情報を埋め一意な文字列にする仕組み</td><td>同上</td></tr><tr><td>リンケージ</td><td>名前が翻訳単位を越えて見えるか(外部/内部)</td><td>同上</td></tr><tr><td>ABI</td><td>バイナリレベルの互換性の取り決め。処理系間で異なる</td><td>同上</td></tr><tr><td>静的/動的リンク</td><td>ライブラリを実行ファイルに焼き込む/実行時に結合する</td><td><a href="/study/runtime/cpp-internals/object-files-and-libraries.html">ライブラリ</a></td></tr><tr><td>DLL</td><td>Windowsの動的ライブラリ</td><td>同上</td></tr><tr><td>テンプレートの実体化</td><td>使用時に型ごとの実物コードが生成されること</td><td><a href="/study/runtime/cpp-internals/template-instantiation-and-inline.html">実体化とinline</a></td></tr><tr><td>vtable / vptr</td><td>型ごとの仮想関数表/各オブジェクトが持つ表へのポインタ</td><td><a href="/study/runtime/cpp-internals/vtable-and-virtual-calls.html">vtable</a></td></tr><tr><td>脱仮想化</td><td>型が証明できる仮想呼び出しを直接呼び出しに変える最適化</td><td>同上</td></tr><tr><td>RTTI</td><td>実行時型情報。typeidとdynamic_castの基盤</td><td><a href="/study/runtime/cpp-internals/exceptions-and-rtti-impl.html">RTTIと例外の実装</a></td></tr><tr><td>ゼロコスト例外</td><td>投げなければほぼ無料、投げたら高い例外実装方式</td><td>同上</td></tr><tr><td>アラインメント</td><td>型ごとの「この倍数のアドレスに置く」要求</td><td><a href="/study/runtime/cpp-internals/memory-layout.html">メモリレイアウト</a></td></tr><tr><td>パディング</td><td>アラインメントのため構造体に入る詰め物</td><td>同上</td></tr><tr><td>エンディアン</td><td>複数バイト数値のバイト順(リトル/ビッグ)</td><td>同上</td></tr><tr><td>コールスタック</td><td>戻り先とローカル変数を積む実行の仕組み</td><td><a href="/study/runtime/cpp-internals/function-calls-and-cpu.html">関数呼び出し</a></td></tr><tr><td>呼出規約</td><td>引数・戻り値をどのレジスタ/スタックで渡すかの取り決め</td><td>同上</td></tr><tr><td>レジスタ</td><td>CPU内部の超高速な記憶場所</td><td>同上</td></tr><tr><td>キャッシュライン</td><td>メモリを読む単位(典型64バイト)</td><td><a href="/study/runtime/cpp-internals/cache-branch-simd.html">キャッシュ</a></td></tr><tr><td>分岐予測</td><td>ifの行き先を予測して投機実行するCPU機構</td><td>同上</td></tr><tr><td>SIMD</td><td>1命令で複数データを同時計算する機構</td><td>同上</td></tr><tr><td>as-ifルール</td><td>観測可能な動作が同じなら何をしてもよい、という最適化の原則</td><td><a href="/study/runtime/cpp-internals/optimization-and-ub.html">最適化</a></td></tr><tr><td>ゼロコスト抽象化</td><td>使わない機能の代金は払わない、というC++の設計哲学</td><td>同上</td></tr><tr><td>PCH</td><td>プリコンパイル済みヘッダー。ビルド高速化</td><td><a href="/study/tools/build/build-speed.html">ビルド時間</a></td></tr><tr><td>Unity Build</td><td>複数.cppを結合してコンパイルする高速化(Unityエンジンとは無関係)</td><td>同上</td></tr><tr><td>サニタイザ</td><td>実行時にUB・メモリバグを検出する機構(ASan等)</td><td><a href="/study/tools/build/debugging-and-analysis.html">品質ツール</a></td></tr><tr><td>PDB</td><td>MSVCのデバッグ情報ファイル。クラッシュ解析に必須</td><td><a href="/study/tools/build/build-configurations.html">ビルド構成</a></td></tr><tr><td>未解決外部シンボル</td><td>定義が見つからないリンクエラー</td><td><a href="/study/tools/build/link-errors.html">リンクエラー</a></td></tr></tbody></table><h2 id="メモリ・実行時用語" tabindex="-1">メモリ・実行時用語 <a class="header-anchor" href="#メモリ・実行時用語" aria-label="Permalink to &quot;メモリ・実行時用語&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用語</th><th>一言定義</th><th>詳細</th></tr></thead><tbody><tr><td>記憶域期間</td><td>オブジェクトがいつ生まれいつ死ぬかの分類(自動/静的/動的)</td><td><a href="/study/runtime/memory/storage-duration-and-lifetime.html">記憶域期間</a></td></tr><tr><td>所有権</td><td>オブジェクトを破棄する責任を誰が持つか</td><td><a href="/study/runtime/memory/ownership-and-borrowing.html">所有権と借用</a></td></tr><tr><td>借用</td><td>所有せず一時的に使わせてもらうこと(参照・非所有ポインタ)</td><td>同上</td></tr><tr><td>dangling pointer</td><td>死んだオブジェクトを指すポインタ</td><td><a href="/study/runtime/memory/memory-bugs.html">メモリバグ</a></td></tr><tr><td>use-after-free (UAF)</td><td>解放済みメモリへのアクセス。UBの代表</td><td>同上</td></tr><tr><td>double free</td><td>同じメモリの二重解放</td><td>同上</td></tr><tr><td>memory leak</td><td>解放されないメモリが溜まり続けること</td><td>同上</td></tr><tr><td>buffer overflow</td><td>確保領域の外への読み書き</td><td>同上</td></tr><tr><td>stack overflow</td><td>コールスタックの使い切り(深い再帰・巨大ローカル)</td><td>同上</td></tr><tr><td>data race</td><td>同期なしの並行アクセス(書き込み含む)。UB</td><td><a href="/study/runtime/memory/concurrency-bugs.html">並行バグ</a></td></tr><tr><td>race condition</td><td>タイミングで結果が変わる論理バグ</td><td>同上</td></tr><tr><td>false sharing</td><td>別データが同一キャッシュラインで奪い合いになる性能問題</td><td>同上</td></tr><tr><td>AoS / SoA</td><td>構造体の配列/配列の構造体。データレイアウトの2方式</td><td><a href="/study/runtime/memory/cache-locality-aos-soa.html">AoSとSoA</a></td></tr><tr><td>placement new</td><td>指定したメモリ上にオブジェクトを構築する低レベル機能</td><td><a href="/study/runtime/memory/allocators-and-pools.html">アロケータ</a></td></tr><tr><td>arena allocator</td><td>ポインタを進めるだけの高速アロケータ。一括Reset</td><td>同上</td></tr><tr><td>fragmentation</td><td>確保・解放の繰り返しでヒープに使えない穴が増えること</td><td>同上</td></tr><tr><td>GC</td><td>ガベージコレクション。到達可能性でメモリを自動回収</td><td><a href="/study/runtime/memory/gc-and-csharp-comparison.html">GC比較</a></td></tr><tr><td>GC Alloc</td><td>Unityで管理ヒープ確保を指す俗語。後のGCスパイクの原因</td><td>同上</td></tr></tbody></table><h2 id="unity-ue対応用語" tabindex="-1">Unity/UE対応用語 <a class="header-anchor" href="#unity-ue対応用語" aria-label="Permalink to &quot;Unity/UE対応用語&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用語</th><th>一言定義</th><th>詳細</th></tr></thead><tbody><tr><td>IL2CPP</td><td>C#(IL)をC++に変換してビルドするUnityの仕組み</td><td><a href="/study/languages/csharp/il2cpp.html">IL2CPP</a></td></tr><tr><td>AOT / JIT</td><td>事前コンパイル/実行時コンパイル</td><td>同上</td></tr><tr><td>P/Invoke</td><td>C#からネイティブ関数を呼ぶ仕組み(C ABI経由)</td><td>同上</td></tr><tr><td>Assembly Definition</td><td>Unityのアセンブリ分割・依存宣言の仕組み</td><td><a href="/study/languages/csharp/headers-vs-asmdef.html">ヘッダーとasmdef</a></td></tr><tr><td>UObject</td><td>UEの管理対象基底クラス(リフレクション+GC付き)</td><td><a href="/study/game/unreal/uobject-actor-component.html">UObject</a></td></tr><tr><td>CDO</td><td>Class Default Object。UEがクラスごとに作る雛形インスタンス</td><td>同上</td></tr><tr><td>UPROPERTY</td><td>UEのリフレクション・GC追跡・エディタ公開の印</td><td><a href="/study/game/unreal/gc-and-object-pointers.html">UEのGC</a></td></tr><tr><td>UHT</td><td>Unreal Header Tool。マクロを読んでコードを生成する</td><td><a href="/study/game/unreal/reflection-and-uht.html">リフレクションとUHT</a></td></tr><tr><td>UBT</td><td>Unreal Build Tool。UE独自のビルドシステム</td><td><a href="/study/game/unreal/build-system-ubt.html">UBT</a></td></tr><tr><td>TObjectPtr / TWeakObjectPtr / TSoftObjectPtr</td><td>UObject用の強参照/弱参照/パス参照</td><td><a href="/study/game/unreal/smart-pointers.html">UEのスマートポインタ</a></td></tr><tr><td>Subsystem</td><td>UE公式のService Locator(寿命別のサービス置き場)</td><td><a href="/study/game/unreal/gameplay-framework.html">Gameplay Framework</a></td></tr><tr><td>Blackboard(UE)</td><td>UE標準のAI用データ共有アセット</td><td><a href="/study/game/patterns/behavior-tree-and-blackboard.html">BT</a></td></tr></tbody></table><hr><p><a href="/study/guide/cpp-index.html">目次に戻る</a></p>',16)])])}const p=d(n,[["render",s]]);export{c as __pageData,p as default};
